export const tplById = (id?: string) => TEMPLATE_CATALOG.find((t) => t.id === id);

export function previewOf(id?: string, size = "a4", pages = 1) {
  const t = tplById(id); if (!t) return "";
  return t.previews[`resume-${pages}p-${size}`] || t.previews[`resume-1p-${size}`]
    || Object.values(t.previews)[0] || "";
}
export function fileOf(id: string, doc: TplFile["doc"], size: string, format: string, pages = 1) {
  return tplById(id)?.files.find((f) => f.doc === doc && f.size === size
    && f.format === format && (doc !== "resume" || f.pages === pages));
}
export function gdocOf(id: string, doc: string, size: string, pages = 1) {
  return tplById(id)?.gdocs.find((g) => g.doc === doc && g.size === size
    && (doc !== "resume" || g.pages === pages));
}
