export const nearestWeight = (family: string, want: number) => {
  const w = FONT_WEIGHTS[family]?.weights;
  if (!w || !w.length) return want;
  return w.reduce((a, b) => (Math.abs(b - want) < Math.abs(a - want) ? b : a), w[0]);
};
